#!/usr/bin/env python3
"""Make a self-contained review gallery; does not edit book sources."""
import base64, html, json, re, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).resolve().parent
rows=json.loads((OUT.parent/'removed-figures.json').read_text())
meta={
'fig-option-information':('Building a better decision','Four text steps repeat the chapter’s sequence.','A compact orientation guide may still help readers navigate the chapter.'),
'fig-attention-bottleneck':('Sensory input and behavioral throughput','Two numerical cards repeat the contrast stated immediately above.','A redesigned logarithmic scale could make the enormous difference visible, with the distinct measurement concepts clearly labeled.'),
'fig-sensory-windows':('Different sensory worlds','The species examples are already listed in the adjacent paragraph; most of the graphic is text.','The human–bee comparison introduces a real relationship. An actual side-by-side perceptual example could strengthen it.'),
'fig-context-mechanisms':('Framing, priming, fluency, and defaults','Four definition cards summarize concepts explained in this and neighboring chapters.','The side-by-side distinction may be useful as a reference; concrete examples could turn it into a stronger visual.'),
'fig-cooperation-architecture':('Routes to cooperation','The five supports and their qualifications are developed in the chapter’s prose.','Worth reconsidering: it does show multiple routes converging on cooperation. A clearer mechanism diagram may be preferable to deletion.'),
'fig-social-preference-games-redraw':('Ultimatum, dictator, and menu variants','Text cards repeat game rules and reported patterns already discussed in the text.','Actual game trees, allocations, or action menus could make the treatment differences intuitive.'),
'fig-three-lenses-strategic-behavior':('Three lenses on strategic behavior','The nearby table already compares equilibrium, behavioral reasoning, and population dynamics.','The common starting point and different questions could still provide a useful conceptual map.'),
'fig-social-learning-culture':('Social learning and cumulative culture','The contributors and two possible outcomes are stated in the surrounding prose.','Worth reconsidering: the arrows show contributors converging on accumulation and then diverging toward improvement or copied error.'),
'fig-silence-mechanisms':('Diagnosing silence in groups','Five diagnostic cards overlap with the chapter’s diagnostic table.','A decision tree based on observable clues could be more useful than either repeating the cards or relying only on a table.'),
'fig-story-evidence-braid':('Combining story and evidence','Two lists repeat the neighboring explanation of how story and evidence support a proposal.','The convergence does express complementarity. A worked message annotated with story and evidence could preserve this insight more concretely.'),
'fig-conversation-needs-map':('Practical, emotional, and identity needs','The table immediately above already distinguishes the three needs and suitable questions.','One sentence interpreted through three different conversational contexts could make the distinction vivid.'),
'fig-agreement-design':('Four agreement-design tools','The four tool cards repeat the chapter’s modules.','A worked negotiation showing which tool solves which problem could justify a revised figure.'),
'fig-choice-architecture':('Five questions for choice architecture','The same five questions appear as a numbered list immediately below.','An annotated real choice interface could show where each design question applies.'),
'fig-master-loop-finale':('Obstacle, change, and results','This repeats the Part VII opening diagram, and the adjacent table develops the workflow.','The repeated diagram may serve as a closing reminder, if that navigational benefit is useful.'),
}
roman=['I','II','III','IV','V','VI','VII']
for r in rows:
 src=r['source']; oldpath='docs/'+src.replace('.qmd','.html')
 oldhtml=subprocess.check_output(['git','show','HEAD:'+oldpath],cwd=ROOT,text=True)
 pos=oldhtml.index('id="'+r['id']+'"')
 cap=re.search(r'<figcaption\b.*?</figcaption>',oldhtml[pos:],re.S).group(0)
 caption=html.unescape(re.sub('<[^>]*>','',cap)).strip()
 r['former_number']=caption.split(':',1)[0].replace('\xa0',' ')
 if src.startswith('parts/'):
  n=int(re.search(r'part-(\d+)',src).group(1));r['location']='Part '+roman[n-1]+' opening';r['group']='parts'
  r['title']='Reading questions for Part '+roman[n-1]
  r['reason']='Three question cards repeat the part introduction and the “Questions to carry forward” that follow.'
  r['consider']='These are navigational summaries. They may help orientation even though they add no new explanation.'
 else:
  r['location']=r['former_number'];r['group']='chapters'
  r['title'],r['reason'],r['consider']=meta[r['id']]
 r['image']='data:image/svg+xml;base64,'+base64.b64encode((ROOT/r['asset']).read_bytes()).decode()
 r['context']='../../../docs/'+src.replace('.qmd','.html')+'#'+r['id']
rows.sort(key=lambda r:(r['group']=='parts',int(re.search(r'(?:chapters/|part-)(\d+)',r['source']).group(1)),r['id']))
# Preserve figure order within chapters using the number recovered from the old rendered book.
rows.sort(key=lambda r:(r['group']=='parts',tuple(map(int,re.findall(r'\d+',r['former_number']))) if r['group']=='chapters' else (int(re.search(r'part-(\d+)',r['source']).group(1)),)))
esc=html.escape
nav=''.join(f'<a href="#{esc(r["id"])}" data-group="{r["group"]}"><strong>{esc(r["location"])}</strong><span>{esc(r["title"])}</span></a>' for r in rows)
cards=[]
for r in rows:
 replacement = '<p class="implemented"><strong>Update: replacement completed.</strong> At your request, this original has been replaced in Chapter 3 by a four-panel animal illustration. <a href="../../../figures/sensory-worlds-illustrated.png" target="_blank">View the new illustration ↗</a></p>' if r['id']=='fig-sensory-windows' else ''
 cards.append(f'''<article id="{esc(r['id'])}" data-group="{r['group']}">
 <header><p class="eyebrow">{esc(r['location'])} · original placement</p><h2>{esc(r['title'])}</h2></header>{replacement}
 <a class="original" href="{r['image']}" target="_blank" aria-label="Open original figure"><img src="{r['image']}" alt="{esc(r['caption'])}" loading="lazy"></a>
 <details><summary>Original caption</summary><p>{esc(r['caption'])}</p></details>
 <div class="rationale"><div><h3>Why I removed it</h3><p>{esc(r['reason'])}</p></div><div><h3>Reason to retain or redesign</h3><p>{esc(r['consider'])}</p></div></div>
 <footer><label>Your decision <select data-id="{esc(r['id'])}" aria-label="Decision for {esc(r['location'])}"><option value="">Undecided</option><option>Restore</option><option>Redesign</option><option>Keep removed</option></select></label><a href="{r['context']}" target="_blank">Read current chapter context ↗</a></footer>
 <label class="note-label">Your note <textarea data-note="{esc(r['id'])}" rows="2" placeholder="What should be kept or changed?"></textarea></label>
 </article>''')
style='''dialog{max-width:96vw;width:1400px;max-height:94vh;padding:60px 24px 24px;border:1px solid #b5c9d4;border-radius:12px;overflow:auto}dialog::backdrop{background:#153347a8}dialog img{display:block;max-width:none;min-width:760px;height:auto;margin:auto}#close-zoom{position:sticky;top:0;z-index:3;display:block;margin:-40px 0 20px auto;background:#143b56;color:white}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:25px}body{margin:0;background:#f4f6f8;color:#1b3046;font:16px/1.55 system-ui,-apple-system,sans-serif}a{color:#126c79}button,select,textarea{font:inherit}button,select{padding:8px 12px;border:1px solid #aebecb;border-radius:7px;background:white;color:#1b3046;cursor:pointer}button:hover{background:#ecf6f6}.wrap{max-width:1480px;margin:auto;display:grid;grid-template-columns:260px minmax(0,1fr);gap:30px;padding:30px}aside{position:sticky;top:20px;align-self:start;max-height:94vh;overflow:auto;padding:8px 10px}aside h2{font-size:17px;margin-top:0}nav a{display:block;text-decoration:none;border-bottom:1px solid #dce3e8;padding:10px 2px}nav span{display:block;color:#506376;font-size:13px}nav strong{font-size:14px}.intro,article{background:white;border:1px solid #d7e0e7;border-radius:14px;padding:28px;margin-bottom:28px}.intro h1{font-size:32px;line-height:1.2;margin:0 0 12px}.intro p{max-width:80ch}h2{font-size:25px;line-height:1.25;margin:0 0 20px}h3{font-size:15px;margin:0 0 7px}.eyebrow{text-transform:uppercase;letter-spacing:.08em;color:#167382;font-size:13px;font-weight:650;margin:0 0 8px}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.implemented{background:#eaf5ef;padding:14px;border-left:4px solid #287c63;border-radius:5px}.muted{color:#586c7d;font-size:14px}.original{display:block;background:white;text-align:center;border:1px solid #e4e9ed;border-radius:9px;padding:16px;overflow:auto}.original img{display:block;width:100%;height:auto;max-width:1200px;margin:auto}article[data-group=parts] .original img{max-width:700px}.rationale{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:22px 0}.rationale p{margin:0;font-size:15px}details{margin-top:14px;color:#536779;font-size:14px}summary{cursor:pointer}footer{border-top:1px solid #e4e9ed;padding-top:18px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}footer a{font-size:14px}label select{margin-left:8px}.note-label{display:block;color:#536779;font-size:14px;margin-top:16px}textarea{display:block;width:100%;margin-top:5px;border:1px solid #b9c8d3;border-radius:7px;padding:8px;color:#20394f;background:#fbfcfd}#export{width:100%;height:160px;margin-top:16px}#selection-message{font-size:14px;color:#4e6576}button:focus-visible,a:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #208e9c;outline-offset:3px}[hidden]{display:none!important}@media(max-width:850px){.wrap{display:block;padding:14px}aside{position:static;max-height:260px;margin-bottom:20px}nav{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.intro,article{padding:18px}.intro h1{font-size:27px}.rationale{grid-template-columns:1fr;gap:16px}h2{font-size:22px}.original{padding:4px}}@media print{aside,.controls,footer,.note-label,#selection-message,#export{display:none!important}.wrap{display:block;padding:0}.intro,article{break-inside:avoid;border:0;padding:16px}body{background:white}details{display:block}}'''
data=[{k:r[k] for k in ['id','location','title']} for r in rows]
js='''document.querySelectorAll('.original').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();document.querySelector('#zoom img').src=a.querySelector('img').src;document.getElementById('zoom').showModal()}));document.getElementById('close-zoom').addEventListener('click',()=>document.getElementById('zoom').close());const items=ITEMS, key='removed-figure-review-20260919';let choices={};try{choices=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}function save(){try{localStorage.setItem(key,JSON.stringify(choices))}catch(e){}document.getElementById('selection-message').textContent=Object.values(choices).filter(x=>x.decision).length+' of 21 decisions recorded in this browser. These choices do not change the book.'}document.querySelectorAll('select[data-id]').forEach(s=>{s.value=choices[s.dataset.id]?.decision||'';s.addEventListener('change',()=>{choices[s.dataset.id]={...choices[s.dataset.id],decision:s.value};save()})});document.querySelectorAll('[data-note]').forEach(n=>{n.value=choices[n.dataset.note]?.note||'';n.addEventListener('input',()=>{choices[n.dataset.note]={...choices[n.dataset.note],note:n.value};save()})});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('article,nav a').forEach(el=>{el.hidden=b.dataset.filter!=='all'&&el.dataset.group!==b.dataset.filter})}));document.getElementById('summary').addEventListener('click',()=>{const lines=items.filter(x=>choices[x.id]?.decision||choices[x.id]?.note).map(x=>x.location+' — '+x.title+': '+(choices[x.id].decision||'Undecided')+(choices[x.id].note?'\nNote: '+choices[x.id].note:''));const out=document.getElementById('export');out.hidden=false;out.value=lines.length?lines.join('\n\n'):'No decisions recorded yet.';out.focus();out.select()});save();'''.replace('ITEMS',json.dumps(data)).replace("?'\nNote:","?'\\nNote:").replace("join('\n\n')","join('\\n\\n')")
body='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Removed figures — review gallery</title><style>STYLE</style></head><body><div class="wrap"><aside><h2>Jump to a figure</h2><nav>NAV</nav></aside><main><section class="intro"><p class="eyebrow">Decision in the Making · review</p><h1>Review the removed figures</h1><p><strong>21 placements: 14 chapter figures and seven part-opening diagrams.</strong> There are 20 unique images because the Part VII diagram also appeared in Chapter 41. All original image files remain available.</p><p>Numbers below are from the book <strong>before removal</strong>. Click a figure to enlarge it. Each original is shown with the reason for removal and a reason to consider retaining or redesigning it. Figures 25.1 and 26.5 especially merit reconsideration because they show relationships.</p><p><strong>Update:</strong> The former Figure 3.3 has now been replaced with a four-panel animal illustration at your request. The original remains below for comparison.</p><p class="muted">Figure 26.4 was redesigned, not deleted, and is not included here. Decisions start undecided. You can record choices and use “Prepare decision summary” to copy them back into the conversation.</p><div class="controls"><button data-filter="all">All 21</button><button data-filter="chapters">Chapter figures</button><button data-filter="parts">Part openings</button><button id="summary">Prepare decision summary</button></div><p id="selection-message" role="status"></p><textarea id="export" hidden aria-label="Decision summary"></textarea></section>CARDS</main></div><dialog id="zoom"><button id="close-zoom" autofocus>Close enlarged figure</button><img alt="Enlarged original figure"></dialog><script>JS</script></body></html>'''.replace('STYLE',style).replace('NAV',nav).replace('CARDS','\n'.join(cards)).replace('<script>JS</script>','<script>'+js+'</script>')
(OUT/'removed-figures.html').write_text(body)
(OUT/'review-index.json').write_text(json.dumps([{k:v for k,v in r.items() if k!='image'} for r in rows],indent=2)+'\n')
print('Wrote',len(rows),'cards to',OUT/'removed-figures.html')
